def keep_one_captain(apps, schema_editor):
    """Antes podía haber varios capitanes: se queda el más antiguo de cada club y los demás pasan a miembros."""
    Membership = apps.get_model("core", "Membership")
    seen = set()
    for membership in Membership.objects.filter(role="admin").order_by("club_id", "id"):
        if membership.club_id in seen:
            membership.role = "member"
            membership.save(update_fields=["role"])
        seen.add(membership.club_id)


